window.DATA = {"cards":[{"id":"c000","term":"Project Charter","def":"Document formally authorizing the project. Names the project manager, defines objectives, and grants authority to use organizational resources.","cat":"Management","sub":"PMP"},{"id":"c001","term":"Stakeholder Register","def":"Document identifying all stakeholders, their interests, influence, and engagement level. Updated throughout the project.","cat":"Management","sub":"PMP"},{"id":"c002","term":"WBS (Work Breakdown Structure)","def":"Hierarchical decomposition of the total scope into manageable work packages. The foundation of scope, schedule, and cost planning.","cat":"Management","sub":"PMP"},{"id":"c003","term":"Critical Path Method","def":"Identifies the longest sequence of dependent tasks determining the minimum project duration. Any delay on the critical path delays the project.","cat":"Management","sub":"PMP"},{"id":"c004","term":"Earned Value Management","def":"Integrates scope, schedule, and cost to measure project performance. Key metrics: PV (planned), EV (earned), AC (actual), SPI, CPI.","cat":"Management","sub":"PMP"},{"id":"c005","term":"SPI / CPI","def":"Schedule Performance Index (EV/PV): >1 is ahead. Cost Performance Index (EV/AC): >1 is under budget. Both measure efficiency.","cat":"Management","sub":"PMP"},{"id":"c006","term":"RACI Matrix","def":"Responsible, Accountable, Consulted, Informed. Clarifies who does what for each deliverable or activity.","cat":"Management","sub":"PMP"},{"id":"c007","term":"Risk Register","def":"Log of identified risks with probability, impact, response strategy, and owner. Living document updated throughout the project.","cat":"Management","sub":"PMP"},{"id":"c008","term":"Risk Response Strategies","def":"Negative: avoid, transfer, mitigate, accept. Positive: exploit, share, enhance, accept. Each risk gets a planned response.","cat":"Management","sub":"PMP"},{"id":"c009","term":"Change Control Board (CCB)","def":"Group responsible for reviewing and approving or rejecting change requests. Ensures changes go through a formal process.","cat":"Management","sub":"PMP"},{"id":"c010","term":"Scope Creep","def":"Uncontrolled expansion of project scope without corresponding adjustments to time, cost, or resources. Prevented by change control.","cat":"Management","sub":"PMP"},{"id":"c011","term":"Predictive vs. Adaptive","def":"Predictive (waterfall): plan-driven, sequential phases. Adaptive (agile): iterative, incremental delivery. Hybrid combines both.","cat":"Management","sub":"PMP"},{"id":"c012","term":"Lessons Learned","def":"Knowledge gained during a project that is documented and shared to improve future projects. Captured throughout, not only at closing.","cat":"Management","sub":"PMP"},{"id":"c013","term":"Procurement Types","def":"Fixed-price (seller bears cost risk), cost-reimbursable (buyer bears cost risk), time-and-materials (hybrid). Selection depends on scope certainty.","cat":"Management","sub":"PMP"},{"id":"c014","term":"TOGAF","def":"The Open Group Architecture Framework. A methodology and set of tools for developing enterprise architecture through the Architecture Development Method.","cat":"Management","sub":"TOGAF"},{"id":"c015","term":"ADM (Architecture Development Method)","def":"TOGAF's core process: Preliminary, Architecture Vision, Business Architecture, IS Architecture, Technology Architecture, Opportunities, Migration Planning, Governance, Change Management.","cat":"Management","sub":"TOGAF"},{"id":"c016","term":"Architecture Repository","def":"Central store of architectural assets: standards, reference models, landscape descriptions, and governance records.","cat":"Management","sub":"TOGAF"},{"id":"c017","term":"Enterprise Continuum","def":"Classification scheme for architecture assets from generic (Foundation Architecture) to specific (Organization-Specific Architecture).","cat":"Management","sub":"TOGAF"},{"id":"c018","term":"Architecture Building Blocks (ABB)","def":"Technology-agnostic functional specifications. Describe what is needed without dictating how it is implemented.","cat":"Management","sub":"TOGAF"},{"id":"c019","term":"Solution Building Blocks (SBB)","def":"Technology-specific components that implement ABBs. Represent actual products, services, or custom solutions.","cat":"Management","sub":"TOGAF"},{"id":"c020","term":"Stakeholder Management in TOGAF","def":"Identifying stakeholders, understanding their concerns, and creating views and viewpoints that address those concerns.","cat":"Management","sub":"TOGAF"},{"id":"c021","term":"Architecture Governance","def":"Practice of managing and controlling architecture at an enterprise level. Ensures compliance with principles, standards, and reference architectures.","cat":"Management","sub":"TOGAF"},{"id":"c022","term":"Scrum Framework","def":"Iterative framework with fixed-length Sprints (1–4 weeks). Three roles: Product Owner, Scrum Master, Developers. Three artifacts: Product Backlog, Sprint Backlog, Increment.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c023","term":"Product Owner","def":"Responsible for maximizing the value of the product by managing the Product Backlog. Single point of accountability for what to build.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c024","term":"Scrum Master","def":"Serves the team by facilitating Scrum events, removing impediments, and coaching on Scrum practices. Not a project manager.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c025","term":"Sprint","def":"Time-boxed iteration (usually 2 weeks) producing a potentially shippable Increment. Scope is negotiable; duration is not.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c026","term":"Sprint Planning","def":"Event where the team selects Product Backlog items for the Sprint and creates a plan to deliver them. Results in the Sprint Backlog.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c027","term":"Daily Scrum / Standup","def":"15-minute daily event for the developers to inspect progress and adapt the plan for the next 24 hours.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c028","term":"Sprint Review","def":"Event at the end of the Sprint where the team demonstrates the Increment to stakeholders and collects feedback.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c029","term":"Sprint Retrospective","def":"Event where the team inspects how the Sprint went and identifies improvements for the next Sprint.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c030","term":"Definition of Done","def":"Shared standard describing when an Increment is complete: coded, tested, documented, reviewed, and deployable.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c031","term":"Product Backlog Refinement","def":"Ongoing activity of adding detail, estimates, and order to Product Backlog items. Keeps the backlog ready for Sprint Planning.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c032","term":"Velocity","def":"Measure of work completed per Sprint, typically in story points. Used for forecasting, not comparison between teams.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c033","term":"User Story","def":"Short description of a feature from the user's perspective: As a [role], I want [capability] so that [benefit]. Includes acceptance criteria.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c034","term":"SAFe (Scaled Agile Framework)","def":"Framework for scaling Agile across large enterprises. Organizes teams into Agile Release Trains (ARTs) aligned to value streams.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c035","term":"Agile Release Train (ART)","def":"SAFe construct: a long-lived team of agile teams (50–125 people) that plans, commits, and executes together in Program Increments.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c036","term":"PI Planning","def":"SAFe's big-room planning event. All ART members align on a shared mission, identify dependencies, and commit to PI objectives for the next 8–12 weeks.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c037","term":"Kanban Board","def":"Visual workflow management tool. Columns represent stages; cards represent work items. WIP limits prevent overload and expose bottlenecks.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c038","term":"WIP Limits","def":"Maximum number of items allowed in a workflow stage. Constraining work in progress improves flow, reduces cycle time, and surfaces problems.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c039","term":"Continuous Integration / Continuous Delivery","def":"CI: merging and testing code frequently. CD: automating deployment so every change is release-ready. Together they accelerate feedback loops.","cat":"Management","sub":"Scrum/SAFe"}],"questions":[{"cat":"Management","sub":"PMP","stem":"The document that formally authorizes a project and names the project manager is:","choices":["The WBS","The scope statement","The project charter","The RACI matrix"],"answer":2,"label":"Project charter","why":"The charter establishes the project, defines objectives, and grants the project manager authority to use resources.","id":"q001","n":1},{"cat":"Management","sub":"PMP","stem":"If a project's CPI is 0.85, this means:","choices":["The project has 85% of scope remaining","The project is under budget","The project is 15% over budget for the work completed","The project is ahead of schedule"],"answer":2,"label":"CPI interpretation","why":"CPI < 1 means the project is getting less value per dollar spent than planned — 85 cents of value for every dollar.","id":"q002","n":2},{"cat":"Management","sub":"PMP","stem":"The critical path in a project schedule is significant because:","choices":["Any delay on it directly delays the project finish date","It contains the easiest tasks","It can be ignored if the team is experienced","It always contains the most expensive tasks"],"answer":0,"label":"Critical path significance","why":"The critical path is the longest sequence of dependent activities. It determines the minimum project duration.","id":"q003","n":3},{"cat":"Management","sub":"PMP","stem":"Scope creep is best prevented by:","choices":["A formal change control process","Allowing the team to make scope decisions independently","Over-estimating the initial scope","Adding buffer time to every task"],"answer":0,"label":"Preventing scope creep","why":"Change control requires formal evaluation and approval of scope changes, preventing uncontrolled expansion.","id":"q004","n":4},{"cat":"Management","sub":"PMP","stem":"A risk response strategy that involves purchasing insurance is:","choices":["Risk transfer","Risk avoidance","Risk mitigation","Risk acceptance"],"answer":0,"label":"Risk transfer","why":"Insurance shifts the financial impact to a third party. The risk still exists; its consequences are transferred.","id":"q005","n":5},{"cat":"Management","sub":"PMP","stem":"In a RACI matrix, the difference between Responsible and Accountable is:","choices":["Accountable does the work; Responsible approves it","Responsible does the work; Accountable is the single person who owns the outcome","They are the same","Responsible is always the project manager"],"answer":1,"label":"R vs. A in RACI","why":"Multiple people can be Responsible, but exactly one person is Accountable — they own the decision and the outcome.","id":"q006","n":6},{"cat":"Management","sub":"PMP","stem":"A fixed-price contract places cost risk primarily on:","choices":["Neither party","The buyer","The seller","Both parties equally"],"answer":2,"label":"Fixed-price risk","why":"If costs exceed the agreed price, the seller absorbs the overrun. The buyer's cost is fixed.","id":"q007","n":7},{"cat":"Management","sub":"Scrum/SAFe","stem":"In Scrum, who is responsible for maximizing the value of the product?","choices":["The development team","The Product Owner","The stakeholders","The Scrum Master"],"answer":1,"label":"Product Owner role","why":"The Product Owner manages the Product Backlog and makes priority decisions to maximize value delivered.","id":"q008","n":8},{"cat":"Management","sub":"Scrum/SAFe","stem":"Sprint duration in Scrum is:","choices":["Changed at each Sprint Retrospective","Fixed and consistent throughout the project","Set by management","Variable based on the amount of work"],"answer":1,"label":"Fixed Sprint duration","why":"Sprint length is time-boxed and does not change. Scope within the Sprint is negotiable, but duration is not.","id":"q009","n":9},{"cat":"Management","sub":"Scrum/SAFe","stem":"The Sprint Retrospective focuses on:","choices":["Demonstrating the Increment to stakeholders","Planning the next Sprint's work","Reviewing the Product Backlog","Inspecting the team's process and identifying improvements"],"answer":3,"label":"Retrospective purpose","why":"The Retro inspects how the Sprint went regarding people, relationships, process, and tools, and plans improvements.","id":"q010","n":10}],"meta":{"total":18,"free":10,"split":true}};
